Deno.test('agrees with an independent 60-digit implementation at the pinned points, poles, wraps and heights included', () => {
  assert(REFERENCE.length >= 130, `${REFERENCE.length} pinned points`)
  for (const [when, heightM, lat, lon, x, y, z] of REFERENCE) {
    const date = new Date(when)
    const got = fieldAt(lat, lon, heightM, date)
    const where = `${when}, ${heightM} m, lat ${lat}, lon ${lon}`
    const h = Math.hypot(x, y)
    assertAlmostEquals(got.xNT, x, 1e-6, `X at ${where}`)
    assertAlmostEquals(got.yNT, y, 1e-6, `Y at ${where}`)
    assertAlmostEquals(got.zNT, z, 1e-6, `Z at ${where}`)
    assertAlmostEquals(got.hNT, h, 1e-6, `H at ${where}`)
    assertAlmostEquals(got.fNT, Math.hypot(h, z), 1e-6, `F at ${where}`)
    assertAlmostEquals(got.inclinationDeg, Math.atan2(z, h) * R2D, 1e-6, `I at ${where}`)
    assert(Math.abs(angDiff(got.unguardedDeclinationDeg, Math.atan2(y, x) * R2D)) < 1e-6, `D at ${where}`)
    // The public function reports the very number the field gives, wherever it reports one.
    const result = declinationDeg(lat, lon, heightM, date)
    if (result.declinationDeg !== null) assertEquals(result.declinationDeg, got.unguardedDeclinationDeg, `declinationDeg() at ${where}`)
  }
})

/** The dense-grid file named by WMM_GRID_JSON, if there is one and this run may read the environment. */
function gridFile(): string | undefined {
  try {
    return Deno.env.get('WMM_GRID_JSON') || undefined
  } catch {
    return undefined
  }
}

Deno.test({
  name: 'agrees with the independent implementation over a dense global grid (opt-in: WMM_GRID_JSON, see the header)',
  ignore: gridFile() === undefined,
  fn() {
    const rows = JSON.parse(Deno.readTextFileSync(gridFile()!)) as Array<{
      iso: string; heightM: number; lat: number; lon: number; x: string; y: string; z: string
    }>
    const worst = { nT: 0, inclinationDeg: 0, declinationDeg: 0 }
    for (const row of rows) {
      const got = fieldAt(row.lat, row.lon, row.heightM, new Date(row.iso))
      const [x, y, z] = [Number(row.x), Number(row.y), Number(row.z)]
      const h = Math.hypot(x, y)
      worst.nT = Math.max(worst.nT, Math.abs(got.xNT - x), Math.abs(got.yNT - y), Math.abs(got.zNT - z), Math.abs(got.hNT - h), Math.abs(got.fNT - Math.hypot(h, z)))
      worst.inclinationDeg = Math.max(worst.inclinationDeg, Math.abs(got.inclinationDeg - Math.atan2(z, h) * R2D))
      worst.declinationDeg = Math.max(worst.declinationDeg, Math.abs(angDiff(got.unguardedDeclinationDeg, Math.atan2(y, x) * R2D)))
    }
    console.log(`dense grid: ${rows.length} points, largest difference ${worst.nT.toExponential(2)} nT, ${worst.inclinationDeg.toExponential(2)} degrees of inclination, ${worst.declinationDeg.toExponential(2)} degrees of declination`)
    assert(rows.length > 10_000)
    assert(worst.nT < 1e-6)
    assert(worst.inclinationDeg < 1e-6)
    assert(worst.declinationDeg < 1e-6)
  },
})

/** Runs python3, or returns undefined when this machine cannot: the check is skipped then, not failed. */
function python(args: string[]): { code: number; stdout: string; stderr: string } | undefined {
  try {
    const out = new Deno.Command('python3', { args, stdout: 'piped', stderr: 'piped' }).outputSync()
    const text = (bytes: Uint8Array) => new TextDecoder().decode(bytes)
    return { code: out.code, stdout: text(out.stdout), stderr: text(out.stderr) }
  } catch {
    return undefined
  }
}
const canRunPython = python(['--version']) !== undefined
const referenceScript = decodeURIComponent(new URL('./wmm_reference.py', import.meta.url).pathname)

Deno.test({
  name: "the reference script's own checks pass, and the pinned table is exactly what it prints (python3 needed)",
  ignore: !canRunPython,
  fn() {
    const checks = python(['-I', '-B', referenceScript])
    assert(checks !== undefined)
    assertEquals(checks.code, 0, checks.stdout + checks.stderr)
    assertEquals((checks.stdout.match(/^PASS /gm) ?? []).length, 4, checks.stdout)
    const printed = python(['-I', '-B', referenceScript, 'table'])
    assert(printed !== undefined)
    assertEquals(printed.code, 0, printed.stderr)
    // The table in this file, from its declaration to its closing bracket, against what the script prints after its comment line.
    const mine = Deno.readTextFileSync(new URL(import.meta.url)).match(/^const REFERENCE[\s\S]*?^\]$/m)?.[0]
    const theirs = printed.stdout.match(/^const REFERENCE[\s\S]*?^\]$/m)?.[0]
    assert(mine !== undefined && theirs !== undefined)
    assertEquals(mine, theirs, 'the pinned table has drifted from wmm_reference.py: regenerate it with `python3 -I -B tests/unit/deno/wmm_reference.py table`')
  },
})

// --- 3. guards ---------------------------------------------------------------------------------------------------

Deno.test('the limits are the ones NOAA publishes: blackout below 2000 nT, caution below 6000 nT, sigma = sqrt(0.26^2 + (5417 / H)^2)', () => {
  assertEquals(BLACKOUT_H_NT, 2000)
  assertEquals(CAUTION_H_NT, 6000)
  assertEquals(SIGMA_D_FLOOR_DEG, 0.26)
  assertEquals(SIGMA_D_FIELD_TERM_NT_DEG, 5417)
  assertEquals(MIN_HEIGHT_M, -1000)
  assertEquals(MAX_HEIGHT_M, 850_000)
  // The model is named as the georeference record names it, from the table's own name.
  assertEquals(DECLINATION_MODEL, WMM_MODEL_NAME.replace('-', ''))
  // WMM2025 only:
  assertEquals(DECLINATION_MODEL, 'WMM2025')
})

Deno.test('the blackout and caution limits fall exactly at 2000 nT and 6000 nT, and a NaN is never usable', () => {
  const cases: Array<[number, 'ok' | 'caution' | 'blackout']> = [
    [0, 'blackout'], [1000, 'blackout'], [1999.999999, 'blackout'],
    [2000, 'caution'], [2000.000001, 'caution'], [4000, 'caution'], [5999.999999, 'caution'],
    [6000, 'ok'], [6000.000001, 'ok'], [20_000, 'ok'], [1e9, 'ok'],
    [-1, 'blackout'], [Number.NaN, 'blackout'],
  ]
  for (const [h, want] of cases) assertEquals(statusForHorizontalIntensity(h), want, `H = ${h}`)
})

Deno.test("sigma is NOAA's sqrt(0.26^2 + (5417 / H)^2): values computed outside the module, the floor, and falling with H", () => {
  // Evaluated from the formula with Python's math.sqrt, not by the module: sqrt(0.0676 + (5417 / H)^2).
  const expected: Array<[number, number]> = [
    [2000, 2.7209506151343503], [3371, 1.6278394203475475], [5417, 1.0332473082471592], [6000, 0.9395254268926296],
    [10_000, 0.60086511797574], [20_000, 0.37544603140797744], [40_000, 0.29315513064758053],
  ]
  for (const [h, sigma] of expected) assertAlmostEquals(declinationSigmaDeg(h), sigma, 1e-12, `H = ${h}`)
  assertAlmostEquals(declinationSigmaDeg(1e12), 0.26, 1e-9, 'the floor: 0.26 degrees however strong the field')
  assertEquals(declinationSigmaDeg(2000) > declinationSigmaDeg(6000) && declinationSigmaDeg(6000) > declinationSigmaDeg(40_000), true)
  assertAlmostEquals(declinationSigmaDeg(2000), 2.7, 0.05, 'NOAA: about 2.7 degrees at the blackout limit')
})

/** A usable result: narrows a `Declination` to the members that carry numbers. */
function usable(d: Declination): Extract<Declination, { declinationDeg: number }> {
  assert(d.declinationDeg !== null, `no declination: status ${d.status}`)
  return d
}

Deno.test('a strong-field place is ok, with a declination, a sigma from the formula and the field strength', () => {
  const seattle = declinationDeg(47.6062, -122.3321, 0, TODAY)
  assertEquals(seattle.status, 'ok')
  const ok = usable(seattle)
  const field = fieldAt(47.6062, -122.3321, 0, TODAY)
  assertEquals(ok.declinationDeg, field.unguardedDeclinationDeg)
  assertEquals(ok.hNT, field.hNT)
  assertEquals(ok.sigmaDeg, Math.sqrt(0.26 ** 2 + (5417 / field.hNT) ** 2))
  assert(ok.hNT >= 6000)
  // WMM2025 only:
  assert(ok.declinationDeg > 14 && ok.declinationDeg < 16, `Seattle is about 15 degrees east: ${ok.declinationDeg}`)
})

Deno.test('a weak-field place is caution: the number is given with a larger sigma', () => {
  // WMM2025 only: Resolute Bay, Nunavut, 2026-11-16: H is about 3400 nT, in NOAA's caution zone from the blackout limit up to 6000.
  const resolute = declinationDeg(74.6973, -94.8297, 0, TODAY)
  assertEquals(resolute.status, 'caution')
  const caution = usable(resolute)
  assert(caution.hNT >= 2000 && caution.hNT < 6000, `H = ${caution.hNT}`)
  assertEquals(caution.sigmaDeg, Math.sqrt(0.26 ** 2 + (5417 / caution.hNT) ** 2))
  assert(caution.sigmaDeg > 1, `sigma ${caution.sigmaDeg} is more than a degree here`)
  assertEquals(caution.declinationDeg, fieldAt(74.6973, -94.8297, 0, TODAY).unguardedDeclinationDeg)
})

Deno.test('a blackout place is refused: no declination and no sigma, but the field strength that says why', () => {
  // WMM2025 only: near the two magnetic poles, and at the north geographic pole, where WMM2025 has H about 1800 nT in 2026.
  for (const [lat, lon] of [[86, 160], [-64.5, 136], [90, 0], [90, 77]] as const) {
    const result = declinationDeg(lat, lon, 0, TODAY)
    assertEquals(result.status, 'blackout', `lat ${lat}, lon ${lon}`)
    assertEquals(result.declinationDeg, null)
    assertEquals(result.sigmaDeg, null)
    assertEquals(result.hNT, fieldAt(lat, lon, 0, TODAY).hNT)
    assert(result.hNT !== null && result.hNT < 2000)
  }
  // WMM2025 only: the south geographic pole is not in a blackout zone.
  assertEquals(declinationDeg(-90, 0, 0, TODAY).status, 'ok')
})

Deno.test('the guarded and the unguarded declination do not share a name: a blackout number cannot pass for a guarded one', () => {
  // WMM2025 only: the north geographic pole is in the blackout zone in 2026.
  const pole = fieldAt(90, 0, 0, TODAY)
  assert(pole.hNT < BLACKOUT_H_NT)
  assert(Number.isFinite(pole.unguardedDeclinationDeg), 'the field still has a number there, and says it has no guard')
  assertEquals(declinationDeg(90, 0, 0, TODAY).declinationDeg, null)
  // @ts-expect-error the field has no property named like the guarded declination: compiling this line is the check
  assertEquals(pole.declinationDeg, undefined)
})

Deno.test('across the globe the status follows H, a number comes only with ok and caution, and sigma never drops below 0.26', () => {
  const counts = { ok: 0, caution: 0, blackout: 0 }
  for (const date of [new Date(FIRST_MS), TODAY, new Date(LAST_MS)]) {
    for (let lat = -90; lat <= 90; lat += 2) {
      for (let lon = -180; lon < 180; lon += 6) {
        const r = declinationDeg(lat, lon, 0, date)
        assert(r.status === 'ok' || r.status === 'caution' || r.status === 'blackout', `${lat}, ${lon}: ${r.status}`)
        assert(r.hNT !== null)
        assertEquals(r.status, statusForHorizontalIntensity(r.hNT))
        counts[r.status]++
        if (r.status === 'blackout') {
          assertEquals([r.declinationDeg, r.sigmaDeg], [null, null])
        } else {
          assert(Number.isFinite(r.declinationDeg) && r.declinationDeg > -180 && r.declinationDeg <= 180)
          assert(r.sigmaDeg >= 0.26 && Number.isFinite(r.sigmaDeg))
          assertEquals(r.sigmaDeg, declinationSigmaDeg(r.hNT))
        }
      }
    }
  }
  // Both guards matter somewhere on Earth, and most of Earth is fine.
  assert(counts.blackout > 0 && counts.caution > 0 && counts.ok > counts.caution + counts.blackout, JSON.stringify(counts))
})

Deno.test('100 m of height changes the declination by under 0.01 degrees on the global grid, so a height can be passed as 0', () => {
  let worst = 0
  for (let lat = -88; lat <= 88; lat += 2) {
    for (let lon = -180; lon < 180; lon += 4) {
      const low = declinationDeg(lat, lon, 0, TODAY)
      const high = declinationDeg(lat, lon, 100, TODAY)
      if (low.declinationDeg === null || high.declinationDeg === null) continue
      worst = Math.max(worst, Math.abs(angDiff(high.declinationDeg, low.declinationDeg)))
    }
  }
  assert(worst < 0.01, `the largest change over 100 m of height was ${worst} degrees`)
  assert(worst > 0, 'height is not ignored')
})

Deno.test('true = magnetic + declination, east positive, folded into [0, 360), and refused when there is no declination', () => {
  const east = { status: 'ok', declinationDeg: 15, sigmaDeg: 0.4, hNT: 20_000 } as const
  const west = { status: 'ok', declinationDeg: -14, sigmaDeg: 0.4, hNT: 20_000 } as const
  assertEquals(trueBearingDeg(0, east), 15)
  assertEquals(trueBearingDeg(10, east), 25)
  assertEquals(trueBearingDeg(350, east), 5)
  assertEquals(trueBearingDeg(0, west), 346)
  assertEquals(trueBearingDeg(14, west), 0)
  assertEquals(trueBearingDeg(720 + 10, east), 25)
  const refused: Declination[] = [
    { status: 'blackout', declinationDeg: null, sigmaDeg: null, hNT: 900 },
    { status: 'expired', declinationDeg: null, sigmaDeg: null, hNT: null },
    { status: 'not-yet-valid', declinationDeg: null, sigmaDeg: null, hNT: null },
  ]
  for (const declination of refused) assertEquals(trueBearingDeg(10, declination), null, declination.status)
  // No declination at all (a place with no usable position) is a refusal too, and so is a reading that is not a number.
  assertEquals(trueBearingDeg(10, null), null)
  assertEquals(trueBearingDeg(10, undefined), null)
  for (const reading of [Number.NaN, Infinity, -Infinity]) assertEquals(trueBearingDeg(reading, east), null, `reading ${reading}`)
  // Through the module: at Seattle, where magnetic north is east of true north, a compass reading of 0 is a true bearing east of north.
  const seattle = declinationDeg(47.6062, -122.3321, 0, TODAY)
  const bearing = trueBearingDeg(0, seattle)
  // WMM2025 only:
  assert(bearing !== null && bearing > 14 && bearing < 16)
})

Deno.test('the sign and size are right in the places everyone knows: east of north on the Pacific coast, west on the Atlantic', () => {
  // WMM2025 only: round figures for places whose declination is well known. The tolerance is wide on purpose: this catches a swapped
  // argument or a flipped sign in terms a reader knows, and is not a check of accuracy. The 12 NOAA rows are that check.
  const places: Array<[string, number, number, number]> = [
    ['Seattle', 47.6062, -122.3321, 15], ['Anchorage', 61.2181, -149.9003, 14], ['Los Angeles', 34.0522, -118.2437, 11.3],
    ['Boston', 42.3601, -71.0589, -14], ['New York', 40.7128, -74.006, -12.5], ['Chicago', 41.8781, -87.6298, -4],
    ['London', 51.5074, -0.1278, 1.2], ['Tokyo', 35.6762, 139.6503, -8], ['Sydney', -33.8688, 151.2093, 12.8], ['Cape Town', -33.9249, 18.4241, -26.8],
  ]
  for (const [name, lat, lon, want] of places) {
    const result = declinationDeg(lat, lon, 0, TODAY)
    assert(result.declinationDeg !== null, name)
    assert(Math.abs(result.declinationDeg - want) < 1.5, `${name}: ${result.declinationDeg} against about ${want}`)
  }
})

// --- a place as it is stored -------------------------------------------------------------------------------------

/** A stored GeoPose with the fields these tests care about. */
const pose = (lat: number | null, lng: number | null, altitudeM: number | null = null): Parameters<typeof declinationForGeoPose>[0] => (
  { lat, lng, altitudeM, bearing: null, accuracyM: null }
)

Deno.test('declinationForGeoPose gives declinationDeg\'s answer for a stored place, with the height taken as 0', () => {
  const want = declinationDeg(47.6062, -122.3321, 0, TODAY)
  assertEquals(declinationForGeoPose(pose(47.6062, -122.3321), TODAY), want)
  // A stored altitude is not used: its datum is mean sea level on one platform and the ellipsoid on another, and a
  // sentinel such as -9999 is a number a place can hold, which declinationDeg would refuse.
  for (const altitudeM of [0, 120, -9999, 1e9, Number.NaN]) assertEquals(declinationForGeoPose(pose(47.6062, -122.3321, altitudeM), TODAY), want, `altitude ${altitudeM}`)
  // A longitude is a longitude however it is written.
  assertEquals(declinationForGeoPose(pose(47.6062, -122.3321 + 360), TODAY)?.status, 'ok')
  // The guards pass through: the pole is a blackout, a date outside the model is expired or not yet valid.
  assertEquals(declinationForGeoPose(pose(90, 0), TODAY), declinationDeg(90, 0, 0, TODAY))
  assertEquals(declinationForGeoPose(pose(47.6062, -122.3321), new Date(END_MS)), { status: 'expired', declinationDeg: null, sigmaDeg: null, hNT: null })
  assertEquals(declinationForGeoPose(pose(47.6062, -122.3321), new Date(FIRST_MS - 1)), { status: 'not-yet-valid', declinationDeg: null, sigmaDeg: null, hNT: null })
  // It composes with trueBearingDeg, and where there is no place there is no bearing.
  const bearing = trueBearingDeg(0, declinationForGeoPose(pose(47.6062, -122.3321), TODAY))
  assert(bearing !== null)
  assertEquals(bearing, trueBearingDeg(0, declinationDeg(47.6062, -122.3321, 0, TODAY)))
  assertEquals(trueBearingDeg(0, declinationForGeoPose(pose(null, null), TODAY)), null)
})

Deno.test('declinationForGeoPose gives null, and never throws, for a place or a date that is not usable', () => {
  const unusable: Array<[string, Parameters<typeof declinationForGeoPose>[0]]> = [
    ['no pose', null], ['an undefined pose', undefined],
    ['no latitude', pose(null, -122.3)], ['no longitude', pose(47.6, null)], ['neither', pose(null, null)],
    ['the (0, 0) that means no fix', pose(0, 0)],
    ['a latitude past the pole', pose(90.000001, 0)], ['a latitude past the other pole', pose(-90.000001, 0)], ['a latitude of 95', pose(95, 10)],
    ['a NaN latitude', pose(Number.NaN, 10)], ['an infinite latitude', pose(Infinity, 10)],
    ['a NaN longitude', pose(45, Number.NaN)], ['an infinite longitude', pose(45, -Infinity)],
  ]
  for (const [what, place] of unusable) assertEquals(declinationForGeoPose(place, TODAY), null, what)
  const badDates: Array<[string, unknown]> = [
    ['an invalid Date', new Date(Number.NaN)], ['no date', null], ['an undefined date', undefined], ['a number', 1_700_000_000_000], ['a string', '2026-11-16'],
  ]
  for (const [what, date] of badDates) assertEquals(declinationForGeoPose(pose(47.6, -122.3), date as Date), null, what)
  // The same pole and the same ends of the range that declinationDeg takes are usable places.
  for (const [lat, lng] of [[90, 0], [-90, 0], [90, 1e7], [-90, -1e7]] as const) assert(declinationForGeoPose(pose(lat, lng), TODAY) !== null, `${lat}, ${lng}`)
})

// --- validity ----------------------------------------------------------------------------------------------------

Deno.test('the model is valid from its epoch up to, not including, its limit, and says which side a date is on', () => {
  // WMM2025 only: the window is 2025.0 to 2030.0, that is 2025-01-01 up to, not including, 2030-01-01.
  assertEquals([WMM_EPOCH, WMM_VALID_UNTIL], [2025, 2030])
  const day = (year: number, rest: string) => `${String(year).padStart(4, '0')}${rest}`
  const cases: Array<[string, 'valid' | 'expired' | 'not-yet-valid']> = [
    ['1900-01-01T00:00:00.000Z', 'not-yet-valid'],
    [day(WMM_EPOCH - 1, '-12-31T23:59:59.999Z'), 'not-yet-valid'],
    [day(WMM_EPOCH, '-01-01T00:00:00.000Z'), 'valid'],
    [day(WMM_EPOCH + 2, '-07-02T12:00:00.000Z'), 'valid'],
    [day(WMM_VALID_UNTIL - 1, '-12-31T23:59:59.999Z'), 'valid'],
    [day(WMM_VALID_UNTIL, '-01-01T00:00:00.000Z'), 'expired'],
    [day(WMM_VALID_UNTIL, '-01-01T00:00:00.001Z'), 'expired'],
    ['2100-01-01T00:00:00.000Z', 'expired'],
  ]
  for (const [when, want] of cases) assertEquals(modelValidity(new Date(when)), want, when)
})

Deno.test('outside its validity the module returns no number at all: it never extrapolates', () => {
  const refused: Array<[Date, 'expired' | 'not-yet-valid']> = [
    [new Date(FIRST_MS - 1), 'not-yet-valid'], [new Date('2000-06-01T00:00:00Z'), 'not-yet-valid'],
    [new Date(END_MS), 'expired'], [new Date(END_MS + 365 * 86_400_000), 'expired'], [new Date('2200-01-01T00:00:00Z'), 'expired'],
  ]
  for (const [date, status] of refused) {
    const when = date.toISOString()
    assertEquals(declinationDeg(47.6062, -122.3321, 0, date), { status, declinationDeg: null, sigmaDeg: null, hNT: null }, when)
    assertEquals(magneticField(47.6062, -122.3321, 0, date), null, when)
    assertEquals(trueBearingDeg(10, declinationDeg(47.6062, -122.3321, 0, date)), null, when)
  }
  // Both ends of the window are inside it, with numbers.
  assertEquals(declinationDeg(47.6062, -122.3321, 0, new Date(FIRST_MS)).status, 'ok')
  assertEquals(declinationDeg(47.6062, -122.3321, 0, new Date(LAST_MS)).status, 'ok')
})

Deno.test('a decimal year is the year plus the fraction of it that has passed, by milliseconds: leap years included', () => {
  assertEquals(decimalYear(new Date('2025-01-01T00:00:00.000Z')), 2025)
  assertEquals(decimalYear(new Date('2027-07-02T12:00:00.000Z')), 2027.5)
  assertEquals(decimalYear(new Date('2029-01-01T00:00:00.000Z')), 2029)
  // 2028 has 366 days: 1 July 12:00 is 182.5 of them in.
  assertAlmostEquals(decimalYear(new Date('2028-07-01T12:00:00.000Z')), 2028 + 182.5 / 366, 1e-15)
  assertAlmostEquals(decimalYear(new Date('2028-12-31T23:59:59.999Z')), 2029, 1e-9)
  assert(decimalYear(new Date('2028-12-31T23:59:59.999Z')) < 2029)
  // A year before 100 is read as that year, not as 19xx.
  const ancient = new Date('0050-07-02T00:00:00.000Z')
  assert(decimalYear(ancient) > 50 && decimalYear(ancient) < 51, String(decimalYear(ancient)))
})

Deno.test('the field is continuous through the turn of every year, a leap year included (no 365-day year)', () => {
  // A year taken as 365 days in a leap year would make the field jump at the turn of the year, by the change of one day:
  // 0.13 nT in Z here, and 0.6 nT in X, Y or Z at the worst place on a grid of 5 by 10 degrees.
  for (let year = WMM_EPOCH + 1; year < WMM_VALID_UNTIL; year++) {
    const before = fieldAt(45, 10, 0, new Date(Date.UTC(year, 0, 1) - 1))
    const after = fieldAt(45, 10, 0, new Date(Date.UTC(year, 0, 1)))
    assertAlmostEquals(after.xNT, before.xNT, 1e-6, `X at ${year}`)
    assertAlmostEquals(after.zNT, before.zNT, 1e-6, `Z at ${year}`)
    assertAlmostEquals(after.unguardedDeclinationDeg, before.unguardedDeclinationDeg, 1e-8, `D at ${year}`)
  }
})

Deno.test('arguments that are not numbers in range are refused with a RangeError, before the date is looked at', () => {
  const bad = (lat: number, lon: number, heightM: number, date: Date) => () => declinationDeg(lat, lon, heightM, date)
  const when = TODAY
  for (const lat of [90.000001, -90.000001, Number.NaN, Infinity, -Infinity]) assertThrows(bad(lat, 0, 0, when), RangeError, 'latDeg', `lat ${lat}`)
  for (const lon of [Number.NaN, Infinity, -Infinity]) assertThrows(bad(0, lon, 0, when), RangeError, 'lonDeg', `lon ${lon}`)
  for (const h of [MIN_HEIGHT_M - 0.001, MAX_HEIGHT_M + 0.001, Number.NaN, Infinity]) assertThrows(bad(0, 0, h, when), RangeError, 'heightM', `height ${h}`)
  assertThrows(bad(0, 0, 0, new Date(Number.NaN)), RangeError, 'date')
  assertThrows(bad(0, 0, 0, null as unknown as Date), RangeError, 'date')
  assertThrows(bad(0, 0, 0, 1_700_000_000_000 as unknown as Date), RangeError, 'date')
  assertThrows(() => magneticField(91, 0, 0, when), RangeError)
  assertThrows(() => modelValidity(new Date(Number.NaN)), RangeError)
  assertThrows(() => decimalYear(new Date(Number.NaN)), RangeError)
  // A bad place is a bug even when the date is out of range.
  assertThrows(bad(100, 0, 0, new Date(END_MS + 10 * 365 * 86_400_000)), RangeError, 'latDeg')
  // The limits themselves are in range.
  for (const [lat, lon, h] of [[90, 0, 0], [-90, 0, 0], [0, 1e7, 0], [0, -1e7, MIN_HEIGHT_M], [0, 0, MAX_HEIGHT_M]] as const) {
    assert(['ok', 'caution', 'blackout'].includes(declinationDeg(lat, lon, h, when).status), `${lat}, ${lon}, ${h}`)
  }
})

// --- 4. properties -----------------------------------------------------------------------------------------------

/** The largest second difference of X, Y, Z (nT) and of D (degrees) along a path: small for any smooth line, a jump's size for a break. */
function roughness(points: Array<[number, number]>, date = TODAY): { nT: number; deg: number } {
  const fields = points.map(([lat, lon]) => fieldAt(lat, lon, 0, date))
  let nT = 0
  let deg = 0
  for (let i = 1; i < fields.length - 1; i++) {
    const [a, b, c] = [fields[i - 1], fields[i], fields[i + 1]]
    nT = Math.max(nT, Math.abs(c.xNT - 2 * b.xNT + a.xNT), Math.abs(c.yNT - 2 * b.yNT + a.yNT), Math.abs(c.zNT - 2 * b.zNT + a.zNT))
    deg = Math.max(deg, Math.abs(angDiff(c.unguardedDeclinationDeg, b.unguardedDeclinationDeg) - angDiff(b.unguardedDeclinationDeg, a.unguardedDeclinationDeg)))
  }
  return { nT, deg }
}
const steps = (from: number, to: number, step: number) => Array.from({ length: Math.round((to - from) / step) + 1 }, (_, i) => from + i * step)

Deno.test('the field is smooth across the 180th meridian, the prime meridian and the equator: no jump where a formula could break', () => {
  const windows: Array<[string, Array<[number, number]>]> = [
    ['180th meridian at 45 N', steps(179, 181, 0.01).map((lon) => [45, lon])],
    ['180th meridian at 30 S', steps(179, 181, 0.01).map((lon) => [-30, lon])],
    ['prime meridian at 45 N', steps(-1, 1, 0.01).map((lon) => [45, lon])],
    ['equator at 30 E', steps(-1, 1, 0.01).map((lat) => [lat, 30])],
    ['equator at 100 W', steps(-1, 1, 0.01).map((lat) => [lat, -100])],
  ]
  for (const [name, points] of windows) {
    const { nT, deg } = roughness(points)
    // A smooth line's second difference over 0.01 degrees is thousandths of a nT here; a break would be its own size.
    assert(nT < 0.05, `${name}: second difference ${nT} nT`)
    assert(deg < 2e-5, `${name}: second difference ${deg} degrees`)
  }
})

Deno.test('the field is smooth along whole parallels and meridians: the 180th meridian is not a seam', () => {
  for (const lat of [0, 45, -30]) {
    const { nT, deg } = roughness(steps(-180, 180, 0.05).map((lon) => [lat, lon]))
    assert(nT < 0.5 && deg < 3e-3, `parallel ${lat}: ${nT} nT, ${deg} degrees`)
  }
  for (const lon of [0, 180]) {
    const { nT, deg } = roughness(steps(-60, 60, 0.05).map((lat) => [lat, lon]))
    assert(nT < 0.5 && deg < 3e-3, `meridian ${lon}: ${nT} nT, ${deg} degrees`)
  }
})

Deno.test('a longitude is the same longitude however it is written: 360 degrees makes no difference', () => {
  for (const [lat, lon] of [[45, 30], [-30, -100], [10, 179.5], [60, -179.5], [0, 0]] as const) {
    const base = fieldAt(lat, lon, 0, TODAY)
    for (const turns of [-3, -1, 1, 2, 7]) {
      const other = fieldAt(lat, lon + 360 * turns, 0, TODAY)
      assertAlmostEquals(other.xNT, base.xNT, 1e-8, `X at ${lon} + ${turns} turns`)
      assertAlmostEquals(other.yNT, base.yNT, 1e-8)
      assertAlmostEquals(other.zNT, base.zNT, 1e-8)
    }
  }
  const [west, east] = [fieldAt(45, -180, 0, TODAY), fieldAt(45, 180, 0, TODAY)]
  assertEquals([west.xNT, west.yNT, west.zNT], [east.xNT, east.yNT, east.zNT])
})

Deno.test('at the geographic poles the field is finite, one vector whatever the longitude, and D turns one degree per degree of longitude', () => {
  for (const when of [TODAY, inWindow(2.5), new Date(LAST_MS)]) {
    for (const [lat, direction] of [[90, 1], [-90, -1]] as const) {
      const reference = fieldAt(lat, 0, 0, when)
      for (const lon of [-180, -135, -90, -45, 0, 30, 45, 90, 135, 180]) {
        const f = fieldAt(lat, lon, 0, when)
        const where = `lat ${lat}, lon ${lon}, ${when.toISOString()}`
        for (const v of [f.xNT, f.yNT, f.zNT, f.hNT, f.fNT, f.inclinationDeg, f.unguardedDeclinationDeg]) assert(Number.isFinite(v), `finite at ${where}`)
        // The same physical vector: the same strength, however north is chosen at the pole ...
        assertAlmostEquals(f.hNT, reference.hNT, 1e-6, `H at ${where}`)
        assertAlmostEquals(f.zNT, reference.zNT, 1e-6, `Z at ${where}`)
        assertAlmostEquals(f.fNT, reference.fNT, 1e-6, `F at ${where}`)
        // ... which turns with the meridian taken as north: D - lon is fixed at the north pole, D + lon at the south pole.
        assert(Math.abs(angDiff(f.unguardedDeclinationDeg - direction * lon, reference.unguardedDeclinationDeg)) < 1e-7, `D at ${where}`)
      }
    }
  }
})

Deno.test('next to a geographic pole the field is the pole\'s: no singularity at cos(latitude) = 0', () => {
  for (const [pole, near] of [[90, 90 - 1e-7], [-90, -90 + 1e-7], [90, 90 - 1e-9], [-90, -90 + 1e-9]] as const) {
    for (const lon of [0, 45, 120, -77]) {
      const there = fieldAt(pole, lon, 0, TODAY)
      const next = fieldAt(near, lon, 0, TODAY)
      assertAlmostEquals(next.xNT, there.xNT, 1e-3, `X, ${near} ${lon}`)
      assertAlmostEquals(next.yNT, there.yNT, 1e-3, `Y, ${near} ${lon}`)
      assertAlmostEquals(next.zNT, there.zNT, 1e-3, `Z, ${near} ${lon}`)
      assert(Math.abs(angDiff(next.unguardedDeclinationDeg, there.unguardedDeclinationDeg)) < 1e-4, `D, ${near} ${lon}`)
    }
  }
  // Approached along a meridian, the field is smooth right up to the pole.
  for (const [from, to] of [[89.9, 90], [-90, -89.9]] as const) {
    const { nT, deg } = roughness(steps(from, to, 0.001).map((lat) => [lat, 30]))
    assert(nT < 1e-3 && deg < 1e-4, `approach to ${to}: ${nT} nT, ${deg} degrees`)
  }
})

Deno.test('the same arguments give the same bits, in any order, and nothing a call is given or reads is changed', () => {
  const places: Array<[number, number, number, Date]> = [
    [47.6062, -122.3321, 0, TODAY], [-90, 12, 0, new Date(FIRST_MS)], [90, -140, 120, new Date(LAST_MS)],
    [0, 0, 9000, inWindow(2.5)], [74.6973, -94.8297, 0, inWindow(3.16)], [-33.8688, 151.2093, 300, inWindow(1.2)],
  ]
  const run = (order: number[]) => order.map((i) => {
    const [lat, lon, h, when] = places[i]
    return { field: magneticField(lat, lon, h, new Date(when)), declination: declinationDeg(lat, lon, h, new Date(when)) }
  })
  const forward = run([0, 1, 2, 3, 4, 5])
  const backward = run([5, 4, 3, 2, 1, 0]).reverse()
  const again = run([0, 1, 2, 3, 4, 5])
  assertEquals(forward, backward)
  assertEquals(forward, again)
  for (let i = 0; i < forward.length; i++) {
    const a = forward[i].field!
    const b = backward[i].field!
    for (const key of Object.keys(a) as Array<keyof MagneticField>) assert(Object.is(a[key], b[key]), `${key} differs in the last bit`)
  }
  // Interleaving calls for other places in between changes nothing.
  const solo = fieldAt(47.6062, -122.3321, 0, TODAY)
  for (let i = 0; i < 50; i++) fieldAt(-60 + i, 3 * i, i * 100, new Date(Date.UTC(WMM_EPOCH + (i % 5), i % 12, 1 + i % 28)))
  assertEquals(fieldAt(47.6062, -122.3321, 0, TODAY), solo)
  // The caller's Date is read, never written; the frozen table is the same table afterwards.
  const date = inWindow(2.5)
  const stamp = date.getTime()
  const table = JSON.stringify(WMM_COEFFICIENTS)
  declinationDeg(10, 20, 30, date)
  magneticField(10, 20, 30, date)
  assertEquals(date.getTime(), stamp)
  assertEquals(JSON.stringify(WMM_COEFFICIENTS), table)
  assert(Object.isFrozen(WMM_COEFFICIENTS) && WMM_COEFFICIENTS.every((row) => Object.isFrozen(row)))
})

// --- 5. the coefficient table ------------------------------------------------------------------------------------

Deno.test('the table has the 90 rows of a degree-12 model in file order, and no h term where m is 0', () => {
  assertEquals(WMM_COEFFICIENTS.length, 90)
  let row = 0
  for (let n = 1; n <= 12; n++) {
    for (let m = 0; m <= n; m++, row++) {
      const [rowN, rowM, g, h, gDot, hDot] = WMM_COEFFICIENTS[row]
      assertEquals([rowN, rowM], [n, m])
      for (const v of [g, h, gDot, hDot]) assert(Number.isFinite(v))
      if (m === 0) assertEquals([h, hDot].map((v) => v === 0), [true, true], `zonal row ${n}`)
    }
  }
  // WMM2025 only: the leading terms, from the first lines of NOAA's file as a reader of it knows them, and the file's name and date.
  assertEquals(WMM_COEFFICIENTS[0], [1, 0, -29351.8, 0, 12, 0])
  assertEquals(WMM_COEFFICIENTS[1], [1, 1, -1410.8, 4545.4, 9.7, -21.5])
  assertEquals(WMM_COEFFICIENTS[89], [12, 12, -0.7, 0.2, -0.1, -0.1])
  assertEquals([WMM_MODEL_NAME, WMM_FILE_DATE], ['WMM-2025', '11/13/2024'])
})

Deno.test('the rows render back to a coefficient file whose SHA-256 is the one the module records: the table is that file', () => {
  const text = renderCof({ epoch: WMM_EPOCH, modelName: WMM_MODEL_NAME, fileDate: WMM_FILE_DATE, rows: WMM_COEFFICIENTS })
  assertEquals(text.split('\n').length, 94, 'a header line, 90 rows, two lines of nines, and the final newline')
  assertEquals(sha256Hex(new TextEncoder().encode(text)), WMM_SOURCE_SHA256)
  // WMM2025 only:
  assertEquals(WMM_SOURCE_SHA256, 'dfa8597825af4e0b87ff4198a5b4fb661b3c49f4cd090cd0164e0259b075582f')
})

const read = (path: string) => Deno.readTextFileSync(new URL(`../../../${path}`, import.meta.url))
/** The generated coefficient module's path: the generator names it after the model. */
const COEFFICIENT_MODULE = `src/world/wmm${WMM_MODEL_NAME.slice(-4)}-coefficients.ts`
/** A source file's comment text as plain words: the comment markers gone and the lines run together. */
const words = (comment: string) => comment.replace(/^\s*\/?\*+\/?/gm, '').replace(/\s+/g, ' ').trim()

Deno.test('the generated header says what the constants say, and carries the NOAA notice', () => {
  const header = words(read(COEFFICIENT_MODULE).split('*/')[0])
  assert(header.includes('GENERATED by scripts/gen-wmm-coefficients.mjs'))
  assert(header.includes(WMM_SOURCE_SHA256))
  assert(header.includes(`epoch ${WMM_EPOCH.toFixed(1)}`) && header.includes(`Valid from ${WMM_EPOCH.toFixed(1)} to ${WMM_VALID_UNTIL.toFixed(1)}`))
  assert(header.includes(`from a file dated ${WMM_FILE_DATE}`) && !header.includes(`released ${WMM_FILE_DATE}`), 'the date on the file is called what it is, not a release date')
  assert(header.includes('17 U.S.C. 403') && header.includes('public domain') && header.includes('not subject to copyright protection'))
  assert(header.includes('consist predominantly of') && header.includes("model's U.S. Government material"), "NCEI's condition is stated as NCEI states it")
  assert(header.includes('as 17 U.S.C. 403 requires') && header.includes('must give notice'), "the requirement is NCEI's statement of what the Act requires, said as NCEI's")
  assert(header.includes('https://www.ncei.noaa.gov/products/world-magnetic-model'))
})

Deno.test('NOTICE.md and THIRD_PARTY.md carry the NOAA notice for the World Magnetic Model data (17 U.S.C. 403)', () => {
  for (const file of ['NOTICE.md', 'THIRD_PARTY.md']) {
    const text = read(file).replace(/\s+/g, ' ')
    const has = (phrase: string) => assert(text.includes(phrase), `${file} says "${phrase}"`)
    has('World Magnetic Model')
    has('17 U.S.C. 403')
    has(COEFFICIENT_MODULE)
    has('public domain')
    // What NCEI asks of a notice: identify the U.S. Government material, and state that it is not subject to copyright protection.
    has('U.S. Government material')
    has('not subject to copyright protection')
    has('https://www.ncei.noaa.gov/products/world-magnetic-model')
    has(`${WMM_EPOCH}.0 to ${WMM_VALID_UNTIL}.0`)
  }
  const notice = read('NOTICE.md').replace(/\s+/g, ' ')
  assert(notice.includes('predominantly'), "NOTICE.md gives NCEI's condition as NCEI states it: works that consist predominantly of the material")
  assert(notice.includes('as 17 U.S.C. 403 requires') && notice.includes('must give notice'), "NOTICE.md says whose requirement it is: NCEI says the Act requires it")
  assert(notice.includes(`December 31, ${WMM_VALID_UNTIL - 1}`), 'NOTICE.md gives the day NOAA says the model expires')
  // The notice's own statement about the coefficients, not only the sentence that says what NCEI asks a notice to state.
  assert(notice.includes('they are U.S. Government material and are not subject to copyright protection'), 'NOTICE.md makes the statement')
  assert(read('THIRD_PARTY.md').replace(/\s+/g, ' ').includes('U.S. Government material and not subject to copyright protection'), 'THIRD_PARTY.md makes the statement')
  assert(read('THIRD_PARTY.md').includes('not NOAA'), "THIRD_PARTY.md says the table was read from a copy and not from NOAA's own download")
})

Deno.test('both modules are browser-safe: no Deno or DOM, and they import only each other and the shared geodesy (ADR 0002)', () => {
  for (const file of ['src/world/declination.ts', COEFFICIENT_MODULE]) {
    const source = read(file)
    assert(!/\bDeno\.[A-Za-z]/.test(source), `${file} uses the Deno namespace`)
    assert(!/\b(document|window|navigator|localStorage)\./.test(source), `${file} touches the DOM`)
    for (const found of source.matchAll(/^(?:import|export)\b[^'"]*from '([^']+)'/gm)) {
      assert(['./enu.ts', './geo.ts', './types.ts'].includes(found[1]) || /^\.\/wmm\d{4}-coefficients\.ts$/.test(found[1]), `${file} imports ${found[1]}`)
    }
  }
})

Deno.test('the module names the model\'s year nowhere in its code but its one import: the swap to the next model changes that line', () => {
  const code = read('src/world/declination.ts')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/\/\/.*$/gm, '')
    .split('\n')
    .filter((line) => !/^import .* from '\.\/wmm\d{4}-coefficients\.ts'$/.test(line))
    .join('\n')
  assertEquals(code.match(/20[2-9]\d/g), null, 'a year in the code would outlive the swap')
  assertEquals(code.match(/wmm-?\d{4}/gi), null, 'a model name in the code would outlive the swap')
  assertEquals(read('src/world/declination.ts').match(/^import .* from '\.\/wmm\d{4}-coefficients\.ts'$/gm)?.length, 1, 'one import of the coefficients')
})

// --- 6. the same on any machine ----------------------------------------------------------------------------------

/** Runs this Deno with the arguments and environment given, or returns undefined when this run may not start processes. */
function deno(args: string[], env: Record<string, string>): { code: number; stdout: string; stderr: string } | undefined {
  try {
    const out = new Deno.Command(Deno.execPath(), { args, env, stdout: 'piped', stderr: 'piped' }).outputSync()
    const text = (bytes: Uint8Array) => new TextDecoder().decode(bytes)
    return { code: out.code, stdout: text(out.stdout), stderr: text(out.stderr) }
  } catch {
    return undefined
  }
}
const canRunDeno = deno(['--version'], {}) !== undefined

Deno.test({
  name: 'dates are read in UTC: the same answers in time zones that are a day ahead of and a day behind UTC (this run, in UTC or not, cannot see the difference)',
  // The time zone is taken from the environment on Linux and macOS only.
  ignore: !canRunDeno || Deno.build.os === 'windows',
  fn() {
    const leapYear = Array.from({ length: WMM_VALID_UNTIL - WMM_EPOCH }, (_, k) => WMM_EPOCH + k).find((y) => new Date(Date.UTC(y, 1, 29)).getUTCMonth() === 1)
    assert(leapYear !== undefined, 'a leap year falls inside the window')
    // The edges of the window, where a local date a day ahead or behind UTC's puts an instant in the wrong year; a leap
    // day; and hours either side of the turn out of a leap year, where the wrong year is also a year of another length, so
    // that the decimal year it gives differs by far more than a rounding error (a millisecond from the turn differs by none).
    const instants = [
      `${WMM_EPOCH - 1}-12-31T23:59:59.999Z`, `${WMM_EPOCH}-01-01T00:00:00.000Z`, `${WMM_EPOCH}-01-01T00:00:00.001Z`,
      `${leapYear}-02-29T12:00:00.000Z`, `${WMM_EPOCH + 1}-07-01T05:30:00.000Z`,
      `${leapYear}-12-31T12:00:00.000Z`, `${leapYear}-12-31T23:00:00.000Z`, `${leapYear + 1}-01-01T01:00:00.000Z`, `${leapYear + 1}-01-01T06:00:00.000Z`,
      `${WMM_VALID_UNTIL - 1}-12-31T23:59:59.999Z`, `${WMM_VALID_UNTIL}-01-01T00:00:00.000Z`,
    ]
    const rowsHere = instants.map((iso) => {
      const date = new Date(iso)
      return [iso, decimalYear(date), modelValidity(date), declinationDeg(47.6062, -122.3321, 0, date)]
    })
    const expected = JSON.parse(JSON.stringify(rowsHere))
    const code = [
      `import { decimalYear, declinationDeg, modelValidity } from ${JSON.stringify(new URL('../../../src/world/declination.ts', import.meta.url).href)}`,
      `const instants = ${JSON.stringify(instants)}`,
      'const rows = instants.map((iso) => { const date = new Date(iso); return [iso, decimalYear(date), modelValidity(date), declinationDeg(47.6062, -122.3321, 0, date)] })',
      'console.log(JSON.stringify({ zoneOffset: new Date(0).getTimezoneOffset(), rows }))',
    ].join('\n')
    // UTC+14, UTC-11 and UTC-3:30: each is a different calendar day from UTC's for part of every day.
    for (const zone of ['Pacific/Kiritimati', 'Pacific/Pago_Pago', 'America/St_Johns']) {
      const ran = deno(['eval', '--no-lock', code], { TZ: zone })
      assert(ran !== undefined)
      assertEquals(ran.code, 0, ran.stderr)
      const got = JSON.parse(ran.stdout.trim().split('\n').at(-1) ?? '')
      assert(got.zoneOffset !== 0, `the time zone ${zone} was not applied, so this run would show nothing`)
      assertEquals(got.rows, expected, `answers in ${zone}`)
    }
  },
})

// --- 7. the replacement reminder ---------------------------------------------------------------------------------

const DAY_MS = 86_400_000
/**
 * Days before the model ends at which the reminder starts to warn. Adopted, not measured (ADR 0005 rule 5): half a
 * year is long enough to put the swap in a plan, and short enough that the warning is not part of the furniture.
 */
const REMINDER_WARN_DAYS = 180
/**
 * Days before the model ends at which the reminder fails the run. Adopted, not measured (ADR 0005 rule 5): NCEI released
 * WMM2025 on 2024-12-17, 15 days before its epoch. Failing from 14 days before the end fires after a release made on that
 * schedule, where a longer lead would block every push while there is nothing yet to swap in. A later release than
 * that is the reason to raise this.
 */
const REMINDER_FAIL_DAYS = 14

/** What the reminder says on a day (milliseconds since 1970): 'ok', 'warn' from 180 days before the model ends, 'due' from 14. */
function replacementReminder(nowMs: number): { level: 'ok' | 'warn' | 'due'; daysLeft: number } {
  const daysLeft = (END_MS - nowMs) / DAY_MS
  return { level: daysLeft <= REMINDER_FAIL_DAYS ? 'due' : daysLeft <= REMINDER_WARN_DAYS ? 'warn' : 'ok', daysLeft }
}

Deno.test('the replacement reminder is quiet until 180 days before the model ends, warns until 14, and is due from there on', () => {
  const day = (daysBeforeEnd: number) => replacementReminder(END_MS - daysBeforeEnd * DAY_MS).level
  assertEquals(day(2000), 'ok')
  assertEquals(day(180.0001), 'ok')
  assertEquals(day(180), 'warn')
  assertEquals(day(100), 'warn')
  assertEquals(day(14.0001), 'warn')
  assertEquals(day(14), 'due')
  assertEquals(day(1), 'due')
  assertEquals(day(0), 'due')
  assertEquals(day(-400), 'due', 'a model that has ended is due')
  // The first model's own dates, as a person would meet them: WMM2025 ends on 2030-01-01 (it expires on 2029-12-31).
  assertEquals(replacementReminder(Date.UTC(WMM_VALID_UNTIL - 1, 6, 4, 23, 59, 59)).level, 'ok')
  assertEquals(replacementReminder(Date.UTC(WMM_VALID_UNTIL - 1, 6, 5)).level, 'warn')
  assertEquals(replacementReminder(Date.UTC(WMM_VALID_UNTIL - 1, 11, 17, 23, 59, 59)).level, 'warn')
  assertEquals(replacementReminder(Date.UTC(WMM_VALID_UNTIL - 1, 11, 18)).level, 'due')
})

Deno.test(`${WMM_MODEL_NAME} is not near its end: the coefficients are replaced before this fails (the header of src/world/declination.ts says how)`, () => {
  const { level, daysLeft } = replacementReminder(Date.now())
  const when = daysLeft >= 0 ? `ends in ${Math.floor(daysLeft)} days` : `ended ${Math.ceil(-daysLeft)} days ago`
  const message = `${WMM_MODEL_NAME} ${when} (it covers dates before ${new Date(END_MS).toISOString().slice(0, 10)}): ` +
    `replace its coefficients with WMM${WMM_VALID_UNTIL}'s, following "WMM${WMM_VALID_UNTIL}: replace the coefficients before ${WMM_VALID_UNTIL}-01-01" in the header of src/world/declination.ts`
  if (level === 'warn') console.warn(`WARNING: ${message}`)
  assert(level !== 'due', message)
})
